from pathlib import Path
from collections import defaultdict, Counter, deque
lines=Path('/app/dataset/genealogy_trees.txt').read_text().splitlines()
W=max(len(l) for l in lines)
lines=[l.ljust(W) for l in lines]
H=len(lines)
# detect boxes
boxes=[]
for y in range(H):
    row=lines[y]
    for x1,ch in enumerate(row):
        if ch!='+':
            continue
        for x2 in range(x1+3, min(W, x1+80)):
            if row[x2] != '+':
                continue
            seg=row[x1:x2+1]
            if not all(ch in '+-~ ' for ch in seg):
                continue
            for h in range(3,12):
                y2=y+h-1
                if y2>=H:
                    continue
                bottom=lines[y2][x1:x2+1]
                if lines[y2][x1] != '+' or lines[y2][x2] != '+':
                    continue
                if not all(ch in '+-~ ' for ch in bottom):
                    continue
                ok=True
                has_alpha=False
                for yy in range(y+1,y2):
                    if lines[yy][x1] not in '|│' or lines[yy][x2] not in '|│':
                        ok=False
                        break
                    inner=lines[yy][x1+1:x2]
                    if any(ch.isalpha() for ch in inner):
                        has_alpha=True
                if ok and has_alpha:
                    texts=[]
                    for yy in range(y+1,y2):
                        t=lines[yy][x1+1:x2].strip()
                        if t:
                            texts.append(t)
                    name=' '.join(texts)
                    boxes.append({'top':y,'left':x1,'bottom':y2,'right':x2,'name':name})
                    break
# dedupe exact coords
uniq=[]
seen=set()
for b in boxes:
    k=(b['top'],b['left'],b['bottom'],b['right'])
    if k not in seen:
        seen.add(k); uniq.append(b)
boxes=uniq
print('boxes', len(boxes))
# map occupied coords for boxes borders to exclude from line graph? We'll exclude text letters anyway; use only line chars outside boxes or on borders except within boxes? Actually borders are line chars and part of graph, but should not connect parent-side to child-side through box; so exclude all box border chars from graph. We'll connect via openings separately.
inside_box=[[False]*W for _ in range(H)]
for bi,b in enumerate(boxes):
    for y in range(b['top'], b['bottom']+1):
        for x in range(b['left'], b['right']+1):
            inside_box[y][x]=True
linechars=set('-~+|│/\\')
coords=[]
idx={}
for y in range(H):
    row=lines[y]
    for x,ch in enumerate(row):
        if ch in linechars and not inside_box[y][x]:
            idx[(y,x)] = len(coords)
            coords.append((y,x,ch))
# build graph
adj=[set() for _ in coords]
# helper to connect if present
for i,(y,x,ch) in enumerate(coords):
    def add(ny,nx):
        j=idx.get((ny,nx))
        if j is not None:
            adj[i].add(j)
    if ch in '-~+':
        add(y,x-1); add(y,x+1)
    if ch in '|│+':
        add(y-1,x); add(y+1,x)
    if ch=='/':
        add(y-1,x+1); add(y+1,x-1)
    if ch=='\\':
        add(y-1,x-1); add(y+1,x+1)
# components
comp=[-1]*len(coords)
cc=0
for i in range(len(coords)):
    if comp[i]!=-1: continue
    dq=[i]; comp[i]=cc
    while dq:
        v=dq.pop()
        for w in adj[v]:
            if comp[w]==-1:
                comp[w]=cc; dq.append(w)
    cc+=1
print('components', cc)
# openings per box
for b in boxes:
    top_ops=[]; bot_ops=[]
    y=b['top']; x1=b['left']; x2=b['right']
    for x in range(x1+1,x2):
        if lines[y][x]==' ' and (y-1>=0 and lines[y-1][x] in linechars):
            top_ops.append(x)
    y=b['bottom']
    for x in range(x1+1,x2):
        if lines[y][x]==' ' and (y+1<H and lines[y+1][x] in linechars):
            bot_ops.append(x)
    b['top_ops']=top_ops; b['bot_ops']=bot_ops
    # link to component ids
    b['top_comps']=sorted({comp[idx[(b['top']-1,x)]] for x in top_ops if (b['top']-1,x) in idx})
    b['bot_comps']=sorted({comp[idx[(b['bottom']+1,x)]] for x in bot_ops if (b['bottom']+1,x) in idx})
# print Dawid and possible parent matches
for b in boxes:
    if b['name']=='Dawid Majtyka':
        print('Dawid box', b)
        target=set(b['top_comps'])
        print('target comps', target)
        for p in boxes:
            if p is b: continue
            if target & set(p['bot_comps']):
                print('possible parent', p['name'], p['top']+1, p['left'], p['bottom']+1, p['right'], p['bot_comps'])
